from lib89 import *
def B(ch,tn,*a,**k): build('maths',ch,tn,*a,**k)
B(9,'Propositions and converses','Propositions, converses and counterexamples','If it rains, the road is wet',
 "If it rains, the road gets wet. But if the road is wet, did it rain? Maybe a tanker spilled water. Reversing a statement can change its truth.",
 [("A proposition is a statement that is either true or false.","proposition"),
  ("The converse of 'if P then Q' is 'if Q then P'.","converse"),
  ("A proposition can be true while its converse is false. 'If a number is divisible by 4 then it is even' is true, but 'if even then divisible by 4' is false.","true but converse false"),
  ("Sometimes both are true: if two sides of a triangle are equal then the opposite angles are equal, and the converse also holds.","both true"),
  ("Sometimes both are false, so we must test each statement separately.","both false"),
  ("A counterexample is one instance that shows a proposition is false. The number 6 is even but not divisible by 4.","counterexample"),
  ("One counterexample is enough to disprove a statement, but many examples cannot prove it for all cases.","one counterexample disproves"),
  ("Mathematicians prove statements with reasoning that works for every case.","proof needs reasoning")],
 ("Write the converse of 'If a quadrilateral is a rectangle, its diagonals are equal' and test it.",[("Converse: if the diagonals of a quadrilateral are equal, it is a rectangle.","Swap P and Q."),("An isosceles trapezium has equal diagonals but is not a rectangle.","Look for a counterexample."),("So the converse is false.","One counterexample is enough.")]),
 ("Explain converse and counterexample with an example.",["Converse swaps the parts","Truth may change","One counterexample disproves"],["Assuming the converse is always true"]),
 ["A proposition is true or false.","The converse of 'if P then Q' is 'if Q then P'.","A true proposition can have a false converse.","A counterexample disproves a proposition."],
 [mcq("m9-1",1,"The converse of 'If P then Q' is","If Q then P",["If not P then not Q","P and Q"],"Converse swaps the two parts."),
  tf("m9-2",1,"A statement and its converse are always both true.",False,"A true statement can have a false converse."),
  mcq("m9-3",1,"A counterexample to 'every even number is divisible by 4' is","6",["8","12"],"6 is even but not divisible by 4."),
  mcq("m9-4",2,"The converse of 'If a number ends in 0 then it is divisible by 5' is 'If a number is divisible by 5 then it ends in 0'. A counterexample to this converse is","15",["20","10"],"15 is divisible by 5 but does not end in 0, so the converse is false."),
  tf("m9-5",2,"Checking many examples proves a statement for all cases.",False,"Only a proof covers all cases."),
  tf("m9-6",2,"If two sides of a triangle are equal, the opposite angles are equal.",True,"This is the isosceles triangle theorem."),
  mcq("m9-7",3,"A statement that is true or false is a","proposition",["converse","counterexample"],"That is the definition."),
  short("m9-8",3,"What disproves a proposition? (two words)",["a counterexample","counterexample","one counterexample"],"One counterexample is enough.")])
B(10,'Weighted mean and stacked charts','Weighted mean and stacked bar charts','Marks that count differently',
 "In a school, the final exam counts for more than a quiz. To combine such scores fairly we give each its weight.",
 [("The weighted mean of x1, x2, ..., xn with weights w1, w2, ..., wn is (w1 x1 + w2 x2 + ... + wn xn) divided by (w1 + w2 + ... + wn).","weighted mean"),
  ("Use it whenever parts of the data have different numbers of values or different importance, such as combining marks of assessments.","use of weights"),
  ("An average of averages can be found with weights equal to the number of values in each group.","average of averages"),
  ("The weighted mean also gives the mean when some values are added or removed, and the concentration of mixtures.","mixtures"),
  ("A stacked bar chart puts parts on top of one another, useful when the total of each bar also matters.","stacked bar chart"),
  ("A 100% stacked bar chart compares proportions, like a pie chart, not absolute values.","100% stacked"),
  ("From a stacked bar chart you can make a 100% stacked chart, but not the other way round.","one-way conversion"),
  ("Always check the weights add to the right total.","check weights")],
 ("A quiz (weight 1) score is 60 and an exam (weight 3) score is 80. Find the weighted mean.",[("Weighted sum = 1 x 60 + 3 x 80 = 300.","Multiply each score by its weight."),("Sum of weights = 4.","Add the weights."),("Weighted mean = 300/4 = 75.","Divide.")]),
 ("When do we use a weighted mean?",["Different importance or group sizes","Multiply by weights then divide by total weight","Gives a fair combined score"],["Using the simple mean when weights differ"]),
 ["Weighted mean = sum of (weight x value) / sum of weights.","It handles unequal importance or group sizes.","Stacked bars show totals; 100% stacked bars show proportions.","A 100% chart cannot be turned back into a stacked chart."],
 [mcq("m10-1",1,"A weighted mean is useful when","values have different importance",["all values are equal","data is empty"],"Weights show importance."),
  tf("m10-2",1,"A 100% stacked bar chart shows absolute values.",False,"It shows proportions."),
  num("m10-3",2,"Weighted mean of 60 (weight 1) and 80 (weight 3)",75,"(60 + 240)/4 = 75.",[(70,"70 is the simple mean.")]),
  num("m10-4",2,"Mean of 10 students with average 40 and 30 students with average 80",70,"(400 + 2400)/40 = 70.",[(60,"60 ignores the group sizes.")]),
  mcq("m10-5",2,"Which chart compares proportions rather than totals?","100% stacked bar chart",["stacked bar chart","dot plot"],"Each bar is scaled to 100%."),
  tf("m10-6",2,"You can always recover a stacked bar chart from a 100% stacked bar chart.",False,"The totals are lost."),
  short("m10-7",3,"In a weighted mean, what do we multiply each value by?",["weight","its weight"],"Each value is multiplied by its weight."),
  mcq("m10-8",3,"The weights 2, 3 and 5 add up to","10",["5","30"],"2 + 3 + 5 = 10.")])
B(11,'Algorithms','Algorithms: steps, conditions and efficiency','A recipe for solving problems',
 "A recipe lists the steps to cook a dish. In mathematics, an algorithm is a recipe for solving a problem, and a computer can follow it exactly.",
 [("An algorithm is a systematic procedure to solve a problem.","algorithm"),
  ("It consists of basic steps that we know how to execute.","basic steps"),
  ("We can repeat a step many times, for example for each j in 1, 2, ..., n, check whether j divides n.","repeat"),
  ("A step can be conditional: add j to the list of divisors of n only if j divides n.","conditional step"),
  ("To list the divisors of 12 we test every j from 1 to 12 and keep those that divide 12: 1, 2, 3, 4, 6, 12.","divisors of 12"),
  ("When we describe an algorithm we must justify that it is correct for every input.","correctness"),
  ("We can also count how many steps it takes in terms of the size of the input, and so judge its efficiency.","efficiency"),
  ("A smarter algorithm may need fewer steps, for example testing j only up to the square root of n.","fewer steps")],
 ("Write the algorithm to find the largest of three numbers a, b, c.",[("Set max = a.","Start with the first number."),("If b > max set max = b; if c > max set max = c.","Conditional steps."),("Output max.","Finish.")]),
 ("What are the features of an algorithm?",["Basic steps","Repeat and condition","Correct and efficient"],["Skipping the check of correctness"]),
 ["An algorithm is a step-by-step procedure.","Steps can repeat and can be conditional.","We must justify correctness.","We can compare algorithms by the number of steps."],
 [mcq("m11-1",1,"An algorithm is","a step-by-step procedure to solve a problem",["a random guess","a single number"],"That is its definition."),
  tf("m11-2",1,"A step in an algorithm can be conditional.",True,"For example, add j only if j divides n."),
  mcq("m11-3",2,"To list the divisors of n we check each j from 1 to n and","keep j if it divides n",["keep every j","remove j if odd"],"The condition is that j divides n."),
  num("m11-4",2,"How many divisors does 12 have?",6,"1, 2, 3, 4, 6, 12.",[(4,"You missed some divisors.")]),
  tf("m11-5",2,"Checking correctness of an algorithm is optional.",False,"We must justify it is correct."),
  mcq("m11-6",2,"Efficiency of an algorithm is judged by","the number of steps it needs",["its colour","its name"],"Fewer steps means more efficient."),
  short("m11-7",3,"The result of repeating a step for each j is called a ___ (one word)",["loop"],"Repeating steps is a loop."),
  mcq("m11-8",3,"Largest of 4, 9, 7 using the algorithm is","9",["4","7"],"9 stays as the maximum.")])
B(12,'Quadrilaterals and midpoint theorem','Quadrilaterals, parallelograms and the midpoint theorem','Four points, one shape',
 "Pick four points and join them: you get a four-sided shape. Which shapes become parallelograms, and what can we prove about them?",
 [("A quadrilateral ABCD joins four points, no three in a line, by segments AB, BC, CD, DA that meet only at the corners.","quadrilateral"),
  ("It is convex when all internal angles are less than 180 degrees, equivalently when its diagonals intersect.","convex"),
  ("A 4-gon is a parallelogram if its opposite sides are equal, or if its opposite angles are equal.","opposite sides or angles equal"),
  ("It is also a parallelogram if its diagonals bisect each other, or if one pair of opposite sides is equal and parallel.","diagonals bisect"),
  ("Midpoint theorem: the line joining the midpoints of two sides of a triangle is parallel to the third side and half its length.","midpoint theorem"),
  ("Converse: a line through the midpoint of one side parallel to a second side bisects the third side.","converse"),
  ("The three medians of a triangle meet at the centroid, which divides each median in the ratio 2 : 1.","centroid 2:1"),
  ("The angles of a quadrilateral add up to 360 degrees.","sum of angles 360")],
 ("In triangle ABC, D and E are midpoints of AB and AC and BC = 10 cm. Find DE.",[("By the midpoint theorem DE is parallel to BC.","Join the midpoints."),("DE = half of BC.","Midpoint theorem."),("DE = 5 cm.","Compute.")]),
 ("State the midpoint theorem and two tests for a parallelogram.",["DE parallel to BC and half of it","Diagonals bisect each other","One pair equal and parallel"],["Forgetting the half"]),
 ["Four conditions make a 4-gon a parallelogram.","Midpoint theorem: parallel and half the third side.","Medians meet at the centroid in the ratio 2 : 1.","Angle sum of a quadrilateral is 360 degrees."],
 [mcq("m12-1",1,"The diagonals of a parallelogram","bisect each other",["are always equal","are always perpendicular"],"This is a property of parallelograms."),
  tf("m12-2",1,"If diagonals of a 4-gon bisect each other it is a parallelogram.",True,"The converse holds."),
  num("m12-3",2,"BC = 10 cm; D and E are midpoints of AB and AC. DE (cm) =",5,"Half of BC.",[(10,"The midpoint segment is half.")]),
  num("m12-4",2,"The angles of a quadrilateral add up to (degrees)",360,"Split into two triangles: 180 + 180.",[(180,"That is for a triangle.")]),
  mcq("m12-5",2,"The centroid divides each median in the ratio","2 : 1",["1 : 1","3 : 1"],"The part from the vertex is twice the other."),
  tf("m12-6",2,"One pair of equal and parallel opposite sides makes a 4-gon a parallelogram.",True,"This is one of the tests."),
  short("m12-7",3,"The meeting point of the medians is the ___",["centroid"],"It is the centroid."),
  mcq("m12-8",3,"A convex quadrilateral has all internal angles","less than 180 degrees",["more than 180","equal to 90 only"],"That is the definition.")])
B(13,'Linear equations in two variables','Linear equations in two variables and their graphs','Two unknowns, one line',
 "Pens cost 10 rupees and notebooks 30 rupees. Many combinations cost the same 100 rupees. All of them sit on one straight line.",
 [("An equation ax + by + c = 0 with a and b not both zero is a linear equation in two variables.","ax + by + c = 0"),
  ("It has infinitely many solutions, and each solution is a pair (x, y).","infinitely many solutions"),
  ("Every point on the graph is a solution and every solution is a point on the graph; the graph is a straight line.","graph is a line"),
  ("The slope-intercept form is y = mx + d. Here m is the slope and d the y-intercept; the line cuts the y-axis at (0, d).","y = mx + d"),
  ("A pair of linear equations can be solved graphically by finding where the two lines meet.","graphical method"),
  ("Algebraically we use substitution or elimination.","substitution, elimination"),
  ("If a1/a2 is not equal to b1/b2 there is one unique solution; if a1/a2 = b1/b2 not equal to c1/c2 there is no solution.","unique or none"),
  ("If a1/a2 = b1/b2 = c1/c2 there are infinitely many solutions because the lines coincide.","coincident lines")],
 ("Solve x + y = 5 and x - y = 1.",[("Add the equations: 2x = 6, so x = 3.","Elimination."),("Substitute: 3 + y = 5, so y = 2.","Find y."),("Check: 3 - 2 = 1.","Verify.")]),
 ("How many solutions can a pair of linear equations have and why?",["Unique, none or infinitely many","Depends on the ratios","Lines meet, are parallel or coincide"],["Believing every pair has exactly one solution"]),
 ["ax + by + c = 0 has infinitely many solutions forming a line.","y = mx + d has slope m and y-intercept d.","Pairs are solved by substitution, elimination or graphs.","Ratios of coefficients decide the number of solutions."],
 [mcq("m13-1",1,"The graph of a linear equation in two variables is","a straight line",["a circle","a parabola"],"Linear means a line."),
  mcq("m13-2",1,"In y = 3x + 2 the y-intercept is","2",["3","0"],"d = 2."),
  tf("m13-3",1,"A linear equation in two variables has infinitely many solutions.",True,"Each point on the line is a solution."),
  num("m13-4",2,"Solve x + y = 5, x - y = 1. Find x.",3,"Adding gives 2x = 6.",[(2,"2 is y.")]),
  num("m13-5",2,"For the same pair, find y.",2,"3 + y = 5.",[(3,"3 is x.")]),
  mcq("m13-6",2,"x + 2y = 4 and 2x + 4y = 8 have","infinitely many solutions",["no solution","one solution"],"The ratios are all equal, so the lines coincide."),
  mcq("m13-7",3,"x + y = 2 and x + y = 5 have","no solution",["one solution","infinitely many"],"Parallel lines never meet."),
  short("m13-8",3,"The slope of y = 4x - 1 is",["4"],"m = 4.")])
B(14,'Surface area and volume','Surface area and volume of solids','Painting and filling',
 "To paint a water tank you need its surface area. To fill it you need its volume. Both depend on its shape.",
 [("A cuboid with length l, width w and height h has surface area 2(wl + hw + lh) and volume whl.","cuboid"),
  ("A right circular cylinder has curved surface area 2 pi r h and volume pi r^2 h.","cylinder volume"),
  ("The total surface area of a cylinder closed at both ends is 2 pi r (h + r).","total surface area"),
  ("A right circular cone has curved surface area pi r l, where l is the slant height, and total surface area pi r (l + r).","cone"),
  ("The volume of a cone is one third pi r^2 h, exactly one third of the cylinder with the same base and height.","cone volume"),
  ("A sphere has surface area 4 pi r^2 and volume four thirds pi r^3.","sphere"),
  ("The slant height of a cone satisfies l^2 = r^2 + h^2.","slant height"),
  ("Surface area is measured in square units and volume in cubic units.","units")],
 ("Find the volume of a cylinder of radius 7 cm and height 10 cm (pi = 22/7).",[("Volume = pi r^2 h.","Use the formula."),("= 22/7 x 49 x 10.","Substitute."),("= 1540 cubic cm.","Compute.")]),
 ("Write the volume formulas for a cuboid, cylinder, cone and sphere.",["whl","pi r^2 h","1/3 pi r^2 h and 4/3 pi r^3"],["Mixing slant height and height"]),
 ["Cuboid: area 2(wl + hw + lh), volume whl.","Cylinder: volume pi r^2 h.","Cone: volume 1/3 pi r^2 h; sphere: 4/3 pi r^3.","Surface area is in square units, volume in cubic units."],
 [mcq("m14-1",1,"Volume of a cuboid is","whl",["2(wl + hw + lh)","pi r^2 h"],"Length x width x height."),
  mcq("m14-2",1,"Volume of a cone with radius r and height h","1/3 pi r^2 h",["pi r^2 h","2 pi r h"],"One third of the cylinder."),
  tf("m14-3",1,"Surface area is measured in cubic units.",False,"It is in square units."),
  num("m14-4",2,"Surface area (sq cm) of a cube of side 3 cm",54,"6 x 9 = 54.",[(27,"27 is the volume.")]),
  num("m14-5",2,"Volume (cubic cm) of a cuboid 5 x 4 x 3",60,"5 x 4 x 3.",[(47,"Do not add.")]),
  num("m14-6",2,"Cone slant height (cm) with r = 3 and h = 4",5,"sqrt(9 + 16) = 5.",[(7,"Use the theorem.")]),
  mcq("m14-7",3,"Surface area of a sphere of radius r","4 pi r^2",["pi r^2","4/3 pi r^3"],"That is the standard result."),
  short("m14-8",3,"Cylinder curved surface area formula (write 2 pi r h or pi r^2 h)",["2 pi r h","2πrh"],"Circumference times height.")])
